import re

def split_fields(line):
    def split_generator(line):
        # Regex pattern to match quoted fields and commas outside of quotes
        pattern = re.compile(r'"([^"]*(?:""[^"]*))*"' | r'([^\s,]+)')
        for match in pattern.finditer(line):
            field = match.group(0)
            if field.startswith('"') and field.endswith('"'):
                # Remove leading and trailing double quotes and unescape doubled quotes
                field = field[1:-1].replace('""', '"')
            yield field

    return list(split_generator(line))
