        return '"' if match.group(0) == '""' else match.group(0)

    result = []
    field_regex = re.compile(r'"([^"]*(?:""[^"]*)*)"|([^,]+)')
    for match in field_regex.finditer(line):
        field = match.group(1) or match.group(2)
        field = re.sub(r'""', match_dquote, field)
