def split_fields(line):
    # Regular expression to match quoted fields and unquoted fields
    pattern = re.compile(r'"((?:[^"\\]|\\.)*)"|([^,]*)')
    fields = []
    current_field = ''
    in_quotes = False

    for match in pattern.finditer(line):
        if match.group(1):
            # Quoted field
            if in_quotes:
                current_field += match.group(1)
                if current_field[-1] == '"':
                    fields.append(current_field[:-1])
                    current_field = ''
                else:
                    in_quotes = True
            else:
                current_field = match.group(1)
        elif match.group(2):
            # Unquoted field
            if in_quotes:
                current_field += match.group(2)
            else:
                fields.append(match.group(2))

    # Handle trailing unquoted field
    if current_field:
        fields.append(current_field)

    return fields
